changeSet.sql:
CREATE OR REPLACE VIEW rpt_cost_line AS SELECT 'LABOR' AS cost_type, l.id AS line_id, l.work_order_id, wo.company_id, wo.title AS work_order_title, wo.status AS work_order_status, wo.asset_id, wo.asset_name, wo.location_id, wo.location_name, wo.category_name AS work_order_category, tc.name AS cost_category, COALESCE(l.started_at, wo.created_at) AS cost_date, (l.hourly_rate * l.duration / 3600) AS amount, ROUND(l.duration / 3600.0, 2) AS hours, TRIM(COALESCE(u.first_name, '') || ' ' || COALESCE(u.last_name, '')) AS assigned_to_name, NULL::varchar AS part_name, NULL::double precision AS quantity FROM labor l JOIN rpt_work_order wo ON l.work_order_id = wo.id LEFT JOIN time_category tc ON l.time_category_id = tc.id LEFT JOIN own_user u ON l.assigned_to_id = u.id
UNION ALL
SELECT 'PART' AS cost_type, pq.id AS line_id, pq.work_order_id, wo.company_id, wo.title AS work_order_title, wo.status AS work_order_status, wo.asset_id, wo.asset_name, wo.location_id, wo.location_name, wo.category_name AS work_order_category, pcat.name AS cost_category, wo.created_at AS cost_date, (p.cost * pq.quantity) AS amount, NULL::numeric AS hours, NULL::text AS assigned_to_name, p.name AS part_name, pq.quantity AS quantity FROM part_quantity pq JOIN rpt_work_order wo ON pq.work_order_id = wo.id JOIN part p ON pq.part_id = p.id LEFT JOIN part_category pcat ON p.category_id = pcat.id
UNION ALL
SELECT 'ADDITIONAL' AS cost_type, ac.id AS line_id, ac.work_order_id, wo.company_id, wo.title AS work_order_title, wo.status AS work_order_status, wo.asset_id, wo.asset_name, wo.location_id, wo.location_name, wo.category_name AS work_order_category, cc.name AS cost_category, COALESCE(ac.date, wo.created_at) AS cost_date, ac.cost AS amount, NULL::numeric AS hours, NULL::text AS assigned_to_name, NULL::varchar AS part_name, NULL::double precision AS quantity FROM additional_cost ac JOIN rpt_work_order wo ON ac.work_order_id = wo.id LEFT JOIN cost_category cc ON ac.category_id = cc.id;
COMMENT ON VIEW rpt_cost_line IS 'Reporting: one row per cost line (LABOR, PART, ADDITIONAL) with work-order context. Tidy shape for pivots and time series.';
